Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='nokeptreading', at=datetime(2026, 11, 16, 0, 0, 0), actor='assistant', title='No reading of a store is kept on disk; a process reads the files, or asks the process that holds the reading', body="A process folds a store from its files, and no fold, skeleton or opened seal is written to disk for a later process to read back. The cost of a first read is cut by having fewer processes pay it. A caller that asks the running server takes the answer only when it names the heads the caller read, and reads the files itself when the server does not answer. The verify verb always reads the files, and the triage pass and the recovery verbs work with the server down. The triage agent's record gains no reader of the server: its process reads the files itself.", rationale="Measured on 2026-11-16, reading a kept skeleton back cost more than the parts it replaced and saved about 2 percent of a cold read; on 2026-11-18 the owner declined to widen the agent's fence to save seconds nobody waits for.", supersedes=()))